import { currentUser } from "@clerk/nextjs/server";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  /** Clerk's user id, once this record has signed in at least once. */
  clerkId?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Real session handling lives in Clerk (see src/proxy.ts). This resolves the
// signed-in Clerk session into our own User record, creating one on first
// sign-in and linking it by clerkId from then on.
export async function getCurrentUser(): Promise<User | undefined> {
  const clerkUser = await currentUser();
  if (!clerkUser) return undefined;

  const email = clerkUser.primaryEmailAddress?.emailAddress ?? clerkUser.emailAddresses[0]?.emailAddress ?? "";

  const existing = users.find((u) => u.clerkId === clerkUser.id || (email && u.email === email));
  if (existing) {
    existing.clerkId ??= clerkUser.id;
    return existing;
  }

  const name = [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") || email || "New user";
  const newUser: User = {
    id: clerkUser.id,
    email,
    name,
    createdAt: new Date(clerkUser.createdAt).toISOString().slice(0, 10),
    clerkId: clerkUser.id,
  };
  users.push(newUser);
  return newUser;
}

